        code: { tr: TV.tr + `\nz = -2.326\nasim = vt["y_r"] < z * vt["v20"]                          # %1 alt getiri eşiği = −2,326 × v20\nprint(f"Test aşımı {asim[v_tst].sum()} / {v_tst.sum()} = %{100 * asim[v_tst].mean():.2f}")\nprint((100 * asim[v_tst].groupby(vt.index[v_tst].year).mean()).round(1).to_string())\nfor w in ["v20", "v60"]:                                  # ölçek mi, kuyruk mu? standartlaştırılmış getirinin eğitimdeki %1 yüzdeliği\n    print(f"Eğitimde y_r / {w}: %1 yüzdelik {np.quantile(vt.loc[v_egt, 'y_r'] / vt.loc[v_egt, w], 0.01):.2f}, std {(vt.loc[v_egt, 'y_r'] / vt.loc[v_egt, w]).std():.2f} (normal: −2,33 ve 1)")`, en: TV.en + `\nz = -2.326\nexc = vt["y_r"] < z * vt["v20"]                           # 1% lower return threshold = −2.326 × v20\nprint(f"Test exceedances {exc[v_tst].sum()} / {v_tst.sum()} = {100 * exc[v_tst].mean():.2f}%")\nprint((100 * exc[v_tst].groupby(vt.index[v_tst].year).mean()).round(1).to_string())\nfor w in ["v20", "v60"]:                                  # scale or tail? the 1% quantile of standardised returns in training\n    print(f"Training y_r / {w}: 1% quantile {np.quantile(vt.loc[v_trn, 'y_r'] / vt.loc[v_trn, w], 0.01):.2f}, std {(vt.loc[v_trn, 'y_r'] / vt.loc[v_trn, w]).std():.2f} (normal: −2.33 and 1)")` },
